update_product.code:
final response = await client.products.updateProduct(101, {
  'invoice_note': 'Ships in 2 business days',
  'advanced': {
    'advance_information': {'mpn': 'MPN-0001'},
  },
});
final product = (response.map as Map)['product'] as Map;
final info = (product['advanced'] as Map)['advance_information'] as Map;
print('${product['invoice_note']} ${info['mpn']}');
print(product['version']);

get_product_stock.code:
final response = await client.products.getProductStock(101);
final stock = response.map as Map;
print(stock['available_stock']);
for (final location in stock['locations'] as List) {
  final row = location as Map;
  print('${row['warehouse']} ${row['warehouse_name']} ${row['stock']}');
}

update_product_stock.code:
final response = await client.products.updateProductStock(101, {
  'note': 'Restock',
  'locations': [
    {'warehouse': 1, 'stock': 10, 'low_stock_level': 2, 'is_default': true},
    {'warehouse': 4, 'stock': 30, 'low_stock_level': 5, 'is_default': false},
  ],
});
final stock = response.map as Map;
print(stock['available_stock']);
for (final location in stock['locations'] as List) {
  print('${(location as Map)['warehouse']} ${location['stock']}');
}
